'use client';

import type { HTMLArkProps } from '@ark-ui/react/factory';
import { ark } from '@ark-ui/react/factory';
import { clsx } from 'clsx';
import { forwardRef } from 'react';
import styles from './Button.module.css';

type ButtonVariant =
  | 'default'
  | 'outline'
  | 'secondary'
  | 'destructive'
  | 'destructive-outline'
  | 'ghost'
  | 'link';

type ButtonSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl' | 'icon-sm' | 'icon-md' | 'icon-lg';

type ButtonRootProps = HTMLArkProps<'button'> & {
  loading?: boolean;
  variant?: ButtonVariant;
  size?: ButtonSize;
  'data-scope'?: string;
  'data-part'?: string;
  'data-slot'?: string;
};

const Button = forwardRef<HTMLButtonElement, ButtonRootProps>(function Button(
  {
    asChild,
    className,
    disabled,
    loading = false,
    onClickCapture,
    size = 'md',
    type,
    'data-scope': dataScope = 'button',
    'data-part': dataPart = 'root',
    'data-slot': dataSlot = 'button-root',
    variant = 'default',
    'aria-busy': ariaBusy,
    'aria-disabled': ariaDisabled,
    ...props
  },
  ref,
) {
  const isDisabled = disabled || loading || ariaDisabled === true || ariaDisabled === 'true';

  return (
    <ark.button
      ref={ref}
      asChild={asChild}
      type={asChild ? type : (type ?? 'button')}
      disabled={asChild ? undefined : isDisabled}
      aria-busy={loading ? true : ariaBusy}
      aria-disabled={isDisabled ? true : ariaDisabled}
      {...props}
      onClickCapture={(event) => {
        if (isDisabled) {
          event.preventDefault();
          event.stopPropagation();
          return;
        }

        onClickCapture?.(event);
      }}
      data-scope={dataScope}
      data-part={dataPart}
      data-slot={dataSlot}
      data-variant={variant}
      data-size={size}
      data-disabled={isDisabled ? '' : undefined}
      data-loading={loading ? '' : undefined}
      className={clsx(styles.root, className)}
    />
  );
});

export { Button };
export type { ButtonRootProps, ButtonSize, ButtonVariant };

@layer moduix.components {
  .root {
    --_button-bg: var(--moduix-color-primary);
    --_button-color: var(--moduix-color-primary-foreground);
    --_button-border-color: var(--moduix-button-bg, var(--_button-bg));
    --_button-bg-hover: color-mix(in srgb, var(--moduix-button-bg, var(--_button-bg)) 88%, black);
    --_button-color-hover: var(--moduix-button-color, var(--_button-color));
    --_button-height: var(--moduix-size-md);
    --_button-padding-x: var(--moduix-spacing-4);
    --_button-padding-y: var(--moduix-spacing-1);
    --_button-font-size: var(--moduix-text-sm);
    --_button-line-height: var(--moduix-line-height-text-sm);

    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--moduix-button-content-gap, var(--moduix-spacing-2));
    margin: 0;
    border: var(--moduix-button-border-width, var(--moduix-border-width-sm)) solid transparent;
    border-radius: var(--moduix-button-radius, var(--moduix-radius-md));
    background-color: transparent;
    appearance: none;
    font: inherit;
    font-weight: var(--moduix-button-font-weight, var(--moduix-weight-medium));
    text-decoration: none;
    user-select: none;
    white-space: nowrap;
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-fast),
      border-color var(--moduix-transition-fast),
      color var(--moduix-transition-fast),
      opacity var(--moduix-transition-fast),
      transform var(--moduix-transition-fast);

    &:focus-visible {
      outline: var(--moduix-focus-ring-width) solid var(--moduix-color-ring);
      outline-offset: calc(var(--moduix-button-border-width, var(--moduix-border-width-sm)) * -1);
    }

    @media (prefers-reduced-motion: no-preference) {
      &[data-slot='button-root']:active:not([data-variant='link'], [aria-haspopup]) {
        transform: translateY(1px);
      }
    }

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
      pointer-events: none;
    }

    & > :where(svg) {
      width: var(--moduix-button-icon-size, var(--moduix-spacing-4));
      height: var(--moduix-button-icon-size, var(--moduix-spacing-4));
      flex-shrink: 0;
    }

    &[data-variant] {
      border-color: var(--moduix-button-border-color, var(--_button-border-color));
      background-color: var(--moduix-button-bg, var(--_button-bg));
      color: var(--moduix-button-color, var(--_button-color));

      @media (hover: hover) {
        &:not([data-disabled]):hover {
          background-color: var(--moduix-button-bg-hover, var(--_button-bg-hover));
          color: var(--_button-color-hover);
        }
      }
    }

    &[data-variant='outline'] {
      --_button-bg: var(--moduix-color-background);
      --_button-color: var(--moduix-color-foreground);
      --_button-border-color: var(--moduix-color-border);
      --_button-bg-hover: var(--moduix-color-accent);
    }

    &[data-variant='secondary'] {
      --_button-bg: var(--moduix-color-secondary);
      --_button-color: var(--moduix-color-secondary-foreground);
      --_button-bg-hover: var(--moduix-color-accent);
    }

    &[data-variant='destructive'] {
      --_button-bg: var(--moduix-color-destructive);
      --_button-color: var(--moduix-color-destructive-foreground);
    }

    &[data-variant='destructive-outline'] {
      --_button-bg: var(--moduix-color-background);
      --_button-color: var(--moduix-color-destructive);
      --_button-border-color: var(--moduix-color-destructive);
      --_button-bg-hover: var(--moduix-color-destructive);
      --_button-color-hover: var(--moduix-color-destructive-foreground);
    }

    &[data-variant='ghost'] {
      --_button-bg: transparent;
      --_button-color: var(--moduix-color-foreground);
      --_button-border-color: transparent;
      --_button-bg-hover: var(--moduix-color-accent);
    }

    &[data-variant='link'] {
      --_button-bg: transparent;
      --_button-color: var(--moduix-color-primary);
      --_button-border-color: transparent;
      --_button-bg-hover: transparent;
      --_button-color-hover: var(--moduix-color-foreground);

      text-decoration: underline;
      text-underline-offset: 0.25em;
    }

    &[data-size='xs'] {
      --_button-height: var(--moduix-size-xs);
      --_button-padding-x: var(--moduix-spacing-2-5);
      --_button-padding-y: var(--moduix-spacing-0-5);
      --_button-font-size: var(--moduix-text-xs);
      --_button-line-height: var(--moduix-line-height-text-xs);
    }

    &[data-size='sm'],
    &[data-size='icon-sm'] {
      --_button-height: var(--moduix-size-sm);
      --_button-padding-x: var(--moduix-spacing-3);
    }

    &[data-size='icon-lg'] {
      --_button-height: var(--moduix-size-lg);
    }

    &[data-size='lg'] {
      --_button-height: var(--moduix-size-lg);
      --_button-padding-x: var(--moduix-spacing-5);
      --_button-padding-y: var(--moduix-spacing-1-5);
      --_button-font-size: var(--moduix-text-md);
      --_button-line-height: var(--moduix-line-height-text-md);
    }

    &[data-size='xl'] {
      --_button-height: var(--moduix-size-xl);
      --_button-padding-x: var(--moduix-spacing-6);
      --_button-padding-y: var(--moduix-spacing-2);
      --_button-font-size: var(--moduix-text-lg);
      --_button-line-height: var(--moduix-line-height-text-lg);
    }

    &[data-size] {
      min-height: var(--moduix-button-height, var(--_button-height));
      padding-block: var(--moduix-button-padding-y, var(--_button-padding-y));
      padding-inline: var(--moduix-button-padding-x, var(--_button-padding-x));
      font-size: var(--moduix-button-font-size, var(--_button-font-size));
      line-height: var(--moduix-button-line-height, var(--_button-line-height));
    }

    &[data-size^='icon-'] {
      width: var(--moduix-button-height, var(--_button-height));
      min-width: var(--moduix-button-height, var(--_button-height));
      height: var(--moduix-button-height, var(--_button-height));
      padding: 0;
      gap: 0;
    }

    &[data-variant='link'] {
      min-height: 0;
      padding-block: 0;
    }
  }
}
